const encoder = new TextEncoder();
const decoder = new TextDecoder();
const FORMAT = 'trabajo-cerca.encrypted-backup.v1';
const ITERATIONS = 310000;
export type CipherPart = { iv: string; content: string };
export type BackupEnvelope = { format: string; id: string; salt: string; iterations: number; parts: CipherPart[] };

function base64(bytes: Uint8Array): string {
  let text = '';
  for (let offset = 0; offset < bytes.length; offset += 8192) text += String.fromCharCode(...bytes.subarray(offset, offset + 8192));
  return btoa(text);
}
function bytes(text: string): Uint8Array {
  return Uint8Array.from(atob(text), character => character.charCodeAt(0));
}
async function keyFor(password: string, salt: Uint8Array) {
  const input = await crypto.subtle.importKey('raw', encoder.encode(password), 'PBKDF2', false, ['deriveKey']);
  return crypto.subtle.deriveKey({ name: 'PBKDF2', salt: salt.buffer as ArrayBuffer, iterations: ITERATIONS, hash: 'SHA-256' }, input, { name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);
}
export async function beginEncryptedBackup(password: string) {
  if (password.length < 12) throw new Error('Usa una contraseña de al menos 12 caracteres.');
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const envelope: BackupEnvelope = { format: FORMAT, id: crypto.randomUUID(), salt: base64(salt), iterations: ITERATIONS, parts: [] };
  return { envelope, key: await keyFor(password, salt) };
}
export async function appendEncrypted(envelope: BackupEnvelope, key: CryptoKey, value: unknown) {
  if (envelope.parts.length >= 2000) throw new Error('Límite de páginas alcanzado. La copia no está completa.');
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const additionalData = encoder.encode(FORMAT + ':' + envelope.id + ':' + envelope.parts.length);
  const ciphertext = await crypto.subtle.encrypt({ name: 'AES-GCM', iv, additionalData }, key, encoder.encode(JSON.stringify(value)));
  envelope.parts.push({ iv: base64(iv), content: base64(new Uint8Array(ciphertext)) });
}
export async function verifyEncryptedBackup(text: string, password: string, visit?: (block: Record<string, unknown>) => Promise<void>) {
  if (text.length > 60000000) throw new Error('El archivo supera el límite de comprobación.');
  const envelope = JSON.parse(text) as BackupEnvelope;
  if (envelope.format !== FORMAT || envelope.iterations !== ITERATIONS || typeof envelope.id !== 'string' || envelope.id.length > 100 || !Array.isArray(envelope.parts) || envelope.parts.length < 1 || envelope.parts.length > 2000) throw new Error('Formato de respaldo no válido.');
  const salt = bytes(envelope.salt);
  if (salt.length !== 16) throw new Error('Sal de cifrado inválida.');
  const key = await keyFor(password, salt);
  const tables = new Map<string, Set<string>>();
  const paths = new Set<string>();
  let manifest: { kind: string; complete: boolean; parts: number; tables: Array<{ table: string; count: number }>; files: number } | null = null;
  for (let index = 0; index < envelope.parts.length; index++) {
    const part = envelope.parts[index];
    const iv = bytes(part.iv);
    if (iv.length !== 12) throw new Error('Bloque cifrado inválido.');
    const clear = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: iv.buffer as ArrayBuffer, additionalData: encoder.encode(FORMAT + ':' + envelope.id + ':' + index) }, key, bytes(part.content).buffer as ArrayBuffer);
    const value = JSON.parse(decoder.decode(clear));
    if (value.kind === 'manifest') {
      if (index !== envelope.parts.length - 1 || manifest) throw new Error('Orden del manifiesto inválido.');
      manifest = value;
    } else if (value.kind === 'table') {
      if (typeof value.table !== 'string' || !Array.isArray(value.items)) throw new Error('Página inválida.');
      const ids = tables.get(value.table) || new Set<string>();
      for (const row of value.items) {
        if (typeof row.id !== 'string' || !row.id || ids.has(row.id)) throw new Error('ID duplicado o ausente. Repite el respaldo.');
        ids.add(row.id);
      }
      tables.set(value.table, ids);
    } else if (value.kind === 'file') {
      if (typeof value.path !== 'string' || typeof value.content !== 'string' || paths.has(value.path)) throw new Error('Archivo duplicado o inválido.');
      paths.add(value.path);
    } else throw new Error('Bloque desconocido.');
    if (visit) await visit(value);
  }
  if (!manifest?.complete || manifest.parts !== envelope.parts.length - 1 || !Array.isArray(manifest.tables) || manifest.tables.length !== tables.size || manifest.files !== paths.size) throw new Error('Respaldo incompleto.');
  const listed = new Set<string>();
  for (const entry of manifest.tables) {
    if (listed.has(entry.table) || !tables.has(entry.table) || tables.get(entry.table)!.size !== entry.count) throw new Error('Inventario de tablas inconsistente.');
    listed.add(entry.table);
  }
  return { tables: tables.size, records: [...tables.values()].reduce((sum, ids) => sum + ids.size, 0), files: paths.size, platformRestoreTested: false };
}

.tcBackupPanel { margin-top: 24px; border-top: 1px solid #dce5de; padding-top: 24px; }
.tcBackupPanel h3 { font-size: 18px; margin: 0; }
.tcBackupFields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; margin-top: 18px; }
.tcBackupFields label { display: flex; flex-direction: column; gap: 7px; font-size: 13px; color: #315344; }
.tcBackupFields input { min-width: 0; min-height: 46px; border: 1px solid #b8c9c2; border-radius: 10px; background: white; padding: 10px 12px; font-size: 16px; color: #163d32; }
.tcBackupActions { display: flex; flex-wrap: wrap; gap: 12px; margin: 18px 0 0; }
.tcBackupActions button, .tcBackupFile { border: 1px solid #b8c9c2; background: #fff; padding: 12px 16px; min-height: 46px; border-radius: 12px; font-size: 14px; }
.tcBackupActions button:first-child { background: #06231c; color: white; }
.tcBackupActions button:disabled { opacity: .5; cursor: not-allowed; }
.tcBackupFile { display: flex; flex-direction: column; gap: 8px; max-width: 100%; }
.tcBackupFile input { max-width: 100%; font-size: 12px; }
.tcBackupPanel summary { cursor: pointer; padding: 12px 0; font-size: 13px; }
.tcBackupPanel :focus-visible { outline: 3px solid #66a80f; outline-offset: 3px; }
@media (max-width: 600px) { .tcBackupFields { grid-template-columns: minmax(0, 1fr); } .tcBackupActions { flex-direction: column; } }

import { useRef, useState } from 'react';
import { RestoreRehearsalPanel } from './restore-panel';
import { api, auth } from '@appdeploy/client';
import { verifyEncryptedBackup } from './backup-crypto';
import { advanceBackup, backupFailure, backupProgress, checkBackupRun, newBackupRun, type BackupRun } from './backup-runner';
import './backup-panel.css';

export function BackupPanel() {
  const [password, setPassword] = useState('');
  const [confirmation, setConfirmation] = useState('');
  const [busy, setBusy] = useState(false);
  const [restoring, setRestoring] = useState(false);
  const [message, setMessage] = useState('Crea una copia cifrada y guárdala fuera de este dispositivo.');
  const [download, setDownload] = useState<{ text: string; complete: boolean } | null>(null);
  const cancelled = useRef(false);
  const run = useRef<BackupRun | null>(null);
  const [canResume, setCanResume] = useState(false);
  const [needsSession, setNeedsSession] = useState(false);

  async function createBackup(resume = false) {
    if (password.length < 12 || password !== confirmation) { setMessage('Usa al menos 12 caracteres y repite la misma contraseña.'); return; }
    setBusy(true); setCanResume(false); setNeedsSession(false); cancelled.current = false;
    try {
      if (!resume || !run.current) { run.current = await newBackupRun(password); setDownload(null); }
      const batchStarted = Date.now();
      let batchSteps = 0;
      while (run.current.phase !== 'complete') {
        if (cancelled.current || ++batchSteps > 1000 || Date.now() - batchStarted > 600000) {
          setCanResume(true);
          setMessage('Copia pausada. El avance se conserva mientras mantengas este panel abierto. Puedes reanudar desde la última página confirmada.');
          break;
        }
        const current = run.current;
        setMessage(backupProgress(current));
        run.current = await advanceBackup(current, async body => {
          const response = await api.post('/api/admin/backup/page', body);
          return response.data;
        });
      }
      if (run.current.phase === 'complete') {
        const checked = await checkBackupRun(run.current, password);
        setDownload({ text: JSON.stringify(run.current.envelope), complete: true });
        setMessage(`Copia cifrada comprobada: ${checked.tables} tablas, ${checked.records} registros y ${checked.files} archivos. Descárgala ahora. Falta probar la restauración en una instancia aislada.`);
      } else if (run.current.envelope.parts.length) {
        setDownload({ text: JSON.stringify(run.current.envelope), complete: false });
      }
    } catch (cause: unknown) {
      const failure = backupFailure(cause);
      if (run.current?.envelope.parts.length) setDownload({ text: JSON.stringify(run.current.envelope), complete: false });
      setCanResume(failure.resumable && Boolean(run.current));
      setNeedsSession(failure.code === 'backup_session');
      const stage = run.current ? backupProgress(run.current) : 'Preparación del cifrado';
      setMessage(`Copia incompleta. Etapa: ${stage}. Código: ${failure.code}. ${failure.message} No se modificaron tus datos.`);
    } finally { setBusy(false); }
  }

  async function resumeBackup() {
    if (needsSession) {
      setBusy(true);
      try { await auth.signIn({ scope: 'openid email profile offline_access' }); }
      catch { setMessage('No se renovó la sesión. El avance sigue disponible en este panel.'); setBusy(false); return; }
    }
    await createBackup(true);
  }

  function discardProgress() {
    run.current = null; setCanResume(false); setDownload(null);
    setMessage('Avance local descartado. Puedes crear una copia nueva. Los datos de la app no se modificaron.');
  }

  function saveDownload() {
    if (!download) return;
    const url = URL.createObjectURL(new Blob([download.text], { type: 'application/json' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = `trabajo-cerca-${download.complete ? 'copia' : 'PARCIAL'}-${new Date().toISOString().slice(0, 10)}.tcbackup`;
    link.click();
    setTimeout(() => URL.revokeObjectURL(url), 30000);
  }

  async function verifyFile(file?: File) {
    if (!file) return;
    if (!password || file.size > 60000000) { setMessage('Ingresa la contraseña de esa copia y selecciona un archivo de menos de 60 MB.'); return; }
    setBusy(true);
    try {
      const result = await verifyEncryptedBackup(await file.text(), password);
      setMessage(`Archivo íntegro: ${result.tables} tablas, ${result.records} registros y ${result.files} archivos. Se comprobó localmente; no se restauró ni modificó la app.`);
    } catch { setMessage('No se pudo validar: contraseña incorrecta, archivo alterado o copia incompleta. No se modificó la app.'); }
    finally { setBusy(false); }
  }

  return (
    <section className='tcBackupPanel' aria-label='Respaldo cifrado'>
      <h3>Respaldo cifrado</h3>
      <p>La contraseña se queda en tu dispositivo. Guárdala por separado: no podremos recuperar una copia si la pierdes.</p>
      <div className='tcBackupFields'>
        <label>Contraseña del respaldo<input type='password' autoComplete='new-password' value={password} onChange={event => setPassword(event.target.value)} disabled={busy || Boolean(run.current)} minLength={12} /></label>
        <label>Repetir contraseña<input type='password' autoComplete='new-password' value={confirmation} onChange={event => setConfirmation(event.target.value)} disabled={busy || Boolean(run.current)} /></label>
      </div>
      <div className='tcBackupActions'>
        {!run.current && <button onClick={() => void createBackup()} disabled={busy || password.length < 12 || password !== confirmation}>Crear copia cifrada</button>}
        {canResume && <button onClick={() => void resumeBackup()} disabled={busy}>{needsSession ? 'Renovar sesión y reanudar' : 'Reanudar copia'}</button>}
        {run.current && !busy && <button onClick={discardProgress}>Descartar avance y crear otra copia</button>}
        {busy && !restoring && <button onClick={() => { cancelled.current = true; }}>Pausar copia</button>}
        {download && <button onClick={saveDownload} disabled={busy}>{download.complete ? 'Descargar copia cifrada' : 'Descargar copia parcial'}</button>}
        <label className='tcBackupFile'>Comprobar una copia<input type='file' accept='.tcbackup,application/json' disabled={busy} onChange={event => { const file = event.target.files?.[0]; event.target.value = ''; void verifyFile(file); }} /></label>
      </div>
      <p role='status' aria-live='polite'>{message}</p>
      <details><summary>Alcance y límites</summary><p>Incluye las tablas identificadas en el código, las tablas referenciadas durante la lectura y los archivos accesibles. No certifica tablas sin referencias ni incluye usuarios o secretos administrados por la plataforma, metadatos originales de archivos ni código fuente. Las lecturas ocurren mientras la app sigue funcionando: esta copia no es una instantánea atómica ni acredita una restauración completa. Los límites detienen la copia sin ocultar fallos. La reanudación conserva el avance solo mientras este panel permanezca abierto; cerrar sesión, recargar o cerrar la app descarta ese avance. Las copias parciales de versiones anteriores no se pueden reanudar.</p></details>
      <RestoreRehearsalPanel password={password} disabled={busy} onBusy={value => { setRestoring(value); setBusy(value); }} />
    </section>
  );
}

import { appendEncrypted, beginEncryptedBackup, verifyEncryptedBackup, type BackupEnvelope } from './backup-crypto';

type Row = Record<string, unknown> & { id: string };
export type BackupPage = { kind: string; table?: string; tables?: string[]; revision?: string; items?: Row[]; paths?: string[]; path?: string; content?: string; nextToken?: string | null };
export type BackupReader = (body: Record<string, unknown>) => Promise<BackupPage>;
export type BackupRun = {
  envelope: BackupEnvelope; key: CryptoKey; startedAt: string; phase: 'scope' | 'tables' | 'storage' | 'files' | 'finish' | 'complete';
  tables: string[]; index: number; cursor: string | null; tokens: string[]; ids: Record<string, string[]>;
  paths: string[]; pendingPaths: string[]; storageNext: string | null; storageTokens: string[]; revision: string;
  calls: number; encryptedBytes: number;
};
const dynamicTable = /^(radar_external_[a-f0-9]{32}|public_feed_page_[0-9]{1,8})$/;
function discover(value: unknown, tables: string[]) {
  if (typeof value === 'string' && dynamicTable.test(value) && !tables.includes(value)) tables.push(value);
  else if (Array.isArray(value)) value.forEach(item => discover(item, tables));
  else if (value && typeof value === 'object') Object.values(value).forEach(item => discover(item, tables));
}
export async function newBackupRun(password: string): Promise<BackupRun> {
  const encrypted = await beginEncryptedBackup(password);
  return { ...encrypted, startedAt: new Date().toISOString(), phase: 'scope', tables: [], index: 0, cursor: null, tokens: [], ids: {}, paths: [], pendingPaths: [], storageNext: null, storageTokens: [], revision: '', calls: 0, encryptedBytes: 0 };
}
export function backupProgress(state: BackupRun) {
  if (state.phase === 'scope') return 'Preparando el inventario';
  if (state.phase === 'tables') return `Datos: tabla ${state.index + 1}/${state.tables.length} (${state.tables[state.index]})`;
  if (state.phase === 'storage' || state.phase === 'files') return `Archivos: ${state.paths.length} completados`;
  return 'Comprobando integridad';
}

// A step works on a copy. Failed reads/encryption never change the last
// committed checkpoint, its encrypted parts, IDs or pagination cursors.
export async function advanceBackup(original: BackupRun, read: BackupReader): Promise<BackupRun> {
  if (original.phase === 'complete') return original;
  if (original.calls >= 5000 || original.tables.length > 500) throw new Error('backup_limit');
  const state: BackupRun = { ...original, envelope: { ...original.envelope, parts: [...original.envelope.parts] }, tables: [...original.tables], tokens: [...original.tokens], ids: { ...original.ids }, paths: [...original.paths], pendingPaths: [...original.pendingPaths], storageTokens: [...original.storageTokens] };
  const ask = async (body: Record<string, unknown>) => { state.calls += 1; return read(body); };
  const add = async (value: unknown) => {
    await appendEncrypted(state.envelope, state.key, value);
    state.encryptedBytes += state.envelope.parts[state.envelope.parts.length - 1].content.length;
    if (state.encryptedBytes > 45000000) throw new Error('backup_limit');
  };
  if (state.phase === 'scope') {
    const scope = await ask({ kind: 'scope' });
    if (!Array.isArray(scope.tables) || !scope.tables.length || scope.tables.some(table => typeof table !== 'string') || new Set(scope.tables).size !== scope.tables.length) throw new Error('invalid_scope');
    state.tables = [...scope.tables]; state.revision = scope.revision || ''; state.phase = 'tables';
  } else if (state.phase === 'tables') {
    const table = state.tables[state.index];
    const page = await ask({ kind: 'table', table, cursor: state.cursor });
    if (page.kind !== 'table' || page.table !== table || !Array.isArray(page.items)) throw new Error('invalid_page');
    const next = page.nextToken || null;
    if (next && state.tokens.includes(next)) throw new Error('pagination_loop');
    const ids = new Set(state.ids[table] || []);
    for (const row of page.items) {
      if (typeof row.id !== 'string' || !row.id || ids.has(row.id)) throw new Error('duplicate_id');
      ids.add(row.id);
    }
    discover(page.items, state.tables);
    await add({ kind: 'table', table, items: page.items });
    state.ids[table] = [...ids];
    state.cursor = next;
    if (next) state.tokens.push(next);
    else { state.index += 1; state.tokens = []; if (state.index === state.tables.length) state.phase = 'storage'; }
  } else if (state.phase === 'storage') {
    const page = await ask({ kind: 'storage', cursor: state.cursor });
    if (!Array.isArray(page.paths) || page.paths.some(path => typeof path !== 'string') || new Set(page.paths).size !== page.paths.length || page.paths.some(path => state.paths.includes(path))) throw new Error('invalid_storage_page');
    const next = page.nextToken || null;
    if (next && state.storageTokens.includes(next)) throw new Error('pagination_loop');
    state.pendingPaths = [...page.paths]; state.storageNext = next;
    if (next) state.storageTokens.push(next);
    state.phase = state.pendingPaths.length ? 'files' : next ? 'storage' : 'finish';
    if (!state.pendingPaths.length) state.cursor = next;
  } else if (state.phase === 'files') {
    const path = state.pendingPaths[0];
    const file = await ask({ kind: 'file', path });
    if (file.kind !== 'file' || file.path !== path || typeof file.content !== 'string') throw new Error('missing_file');
    await add({ kind: 'file', path, content: file.content });
    state.paths.push(path); state.pendingPaths.shift();
    if (!state.pendingPaths.length) { state.cursor = state.storageNext; state.phase = state.cursor ? 'storage' : 'finish'; }
  } else if (state.phase === 'finish') {
    await add({ kind: 'manifest', complete: true, appId: 'trabajo-cerca-laboratorio-3ojgro', revision: state.revision, startedAt: state.startedAt, finishedAt: new Date().toISOString(), consistency: 'rolling_non_atomic', fullPlatformBackup: false, dynamicCatalogueCertified: false, storageMetadataIncluded: false, tables: state.tables.map(table => ({ table, count: (state.ids[table] || []).length })), files: state.paths.length, parts: state.envelope.parts.length });
    state.phase = 'complete';
  }
  return state;
}

export async function checkBackupRun(state: BackupRun, password: string) {
  return verifyEncryptedBackup(JSON.stringify(state.envelope), password);
}

export function backupFailure(cause: unknown): { code: string; message: string; resumable: boolean } {
  const failure = cause as { message?: string; status?: number; statusCode?: number; response?: { status?: number; data?: { error?: string; code?: string } } };
  const status = failure?.response?.status ?? failure?.status ?? failure?.statusCode;
  const code = failure?.response?.data?.code;
  if (status === 429 || code === 'backup_quota') return { code: 'backup_quota', message: 'Se alcanzó una cuota de lectura. Espera antes de reanudar; no se reintentará automáticamente.', resumable: true };
  if (status === 401 || status === 403) return { code: 'backup_session', message: 'La sesión dejó de autorizar la lectura. Recupera la sesión antes de reanudar.', resumable: true };
  if (status === 413) return { code: 'backup_size', message: 'Una página o archivo supera el tamaño admitido. Este caso requiere ampliar el exportador; reanudar ahora repetirá el error.', resumable: false };
  if (status === 409) return { code: 'backup_source_changed', message: 'Un archivo no está disponible o la lectura quedó incompleta. Conserva la copia parcial y crea una copia nueva después de revisar la fuente.', resumable: false };
  const known = ['backup_limit', 'duplicate_id', 'pagination_loop', 'invalid_page', 'invalid_scope', 'invalid_storage_page', 'missing_file'];
  if (known.includes(failure?.message || '')) return { code: failure.message!, message: 'El exportador detectó un límite o una inconsistencia. Conserva la copia parcial; no es un respaldo completo.', resumable: false };
  return { code: code === 'backup_read_incomplete' ? code : 'backup_read_failed', message: 'La lectura no se completó. Puedes reanudar desde la última página confirmada, sin volver a copiar las anteriores.', resumable: true };
}

/** Optional short-lived cache: ONLY approved external Radar jobs.
 * Never saves service profiles, direct postings, contact details or visitor identity.
 * Every app launch revalidates against the authoritative feed. */
const KEY='tc_public_verified_radar_v1';
const FIELDS=['id','kind','origin','title','company','workLocation','workCommunes','recruitmentZones','recruitmentCommunes',
 'area','status','date','until','vacancies','applicationUrl','source','sourceDomain','sourcePublishedAt','url',
 'salary','tags','visual','icon','portalPlace','review','verified','createdAt','firstPublishedAt',
 'lastVerifiedAt','externalVerifiedAt','verifiedAt','verificationMethod','verificationReason','active'] as const;
export function readPublicJobCache<T>():{items:T[];summary:Record<string,unknown>}|null{
 try{
  const d=JSON.parse(localStorage.getItem(KEY)||'null');
  if(!d||d.v!==1||!Number.isFinite(d.at)||d.at>Date.now()||Date.now()-d.at>2*3600000
    ||!Array.isArray(d.items)||d.items.length>1200||!d.summary)return null;
  const items=d.items.filter((r:Record<string,unknown>)=>r.kind==='job_offer'&&r.origin==='radar'
    &&r.verified===true&&r.review===false&&typeof r.id==='string'&&/^[A-Za-z0-9_-]{1,128}$/.test(r.id));
  return items.length?{items,summary:d.summary}:null;
 }catch{return null;}
}
export function writePublicJobCache(rows:Record<string,unknown>[],summary:Record<string,unknown>){
 try{
  const items=rows.filter(x=>x.kind==='job_offer'&&x.origin==='radar'&&x.verified===true&&x.review===false)
   .slice(0,1200).map(row=>{
    const safe:Record<string,unknown>={note:'',apply:''};
    for(const key of FIELDS)if(row[key]!==undefined)safe[key]=row[key];
    return safe;
   });
  if(!items.length)return;
  const totals:Record<string,unknown>={};
  for(const key of ['totalItems','totalJobOffers','totalVerifiedJobOffers','totalProvisionalJobOffers','recentJobOffers7d','recentJobOffers24h','communeStats','kindStats'])totals[key]=summary[key];
  const raw=JSON.stringify({v:1,at:Date.now(),items,summary:totals});
  if(raw.length<600000)localStorage.setItem(KEY,raw);
 }catch{}
}

import {useState} from 'react';
import {api} from '@appdeploy/client';
type Offer={id_fuente:string;cargo:string;empresa:string;comunas:string[];url_original:string;fecha_publicacion:string;fecha_cierre?:string|null;justificacion?:string};
type Result={id:string;status:string;existingId?:string};
export function ChatGPTDirectConnector(){
 const [offers,setOffers]=useState<Offer[]>([]);
 const [results,setResults]=useState<Result[]>([]);
 const [message,setMessage]=useState('Carga el lote JSON y simula antes de importar.');
 const [busy,setBusy]=useState(false),[previewed,setPreviewed]=useState(false);
 async function loadFile(file?:File){
  if(!file)return;
  try{const data=JSON.parse(await file.text()) as {offers?:Offer[]};if(!Array.isArray(data.offers))throw Error('Falta offers[]');
   setOffers(data.offers);setResults([]);setPreviewed(false);setMessage(data.offers.length+' ofertas cargadas.');
  }catch(cause){setMessage(cause instanceof Error?cause.message:'Archivo inválido');}
 }
 async function run(commit:boolean){
  if(!offers.length||(commit&&!previewed))return;
  if(commit&&!window.confirm('¿Incorporar directamente las ofertas aptas al catálogo?'))return;
  setBusy(true);
  try{const response=await api.post('/api/admin/chatgpt-direct-import',{offers,commit});
   const next=response.data.results as Result[];setResults(next);setPreviewed(!commit);
   const counts=new Map<string,number>();for(const x of next)counts.set(x.status,(counts.get(x.status)||0)+1);
   setMessage((commit?'Importación: ':'Simulación: ')+[...counts].map(([s,n])=>s+': '+n).join(' · '));
  }catch(cause){setPreviewed(false);const status=(cause as {response?:{status?:number}}).response?.status;setMessage('No se completó la consulta'+(status?' HTTP '+status:'')+'.');}
  finally{setBusy(false);}
 }
 return <section className='opsCard' aria-label='Importación ChatGPT'>
  <h3>Conector directo ChatGPT</h3><p>Solo administración · no usa las colas de verificación de los motores. Primero verifica en el catálogo vivo.</p>
  <input aria-label='Cargar lote JSON' type='file' accept='.json,application/json' onChange={e=>void loadFile(e.target.files?.[0])}/>
  <div style={{display:'flex',gap:8,flexWrap:'wrap',marginTop:12}}>
   <button disabled={busy||!offers.length} onClick={()=>void run(false)}>Simular</button>
   <button disabled={busy||!previewed||!results.some(x=>x.status==='ready_for_direct_import')} onClick={()=>void run(true)}>Importar aptas</button>
  </div>
  <p role='status'>{message}</p>
  <div style={{maxHeight:250,overflowY:'auto'}}>{results.map(x=><p key={x.id}>{x.id}: {x.status}</p>)}</div>
 </section>;
}

import {useEffect,useState} from 'react';
import './coverage-proposal.css';
import {api} from '@appdeploy/client';
import type {CommercialConfig} from '../shared/commercial-policy';
import {COMMERCIAL_PLACES} from '../shared/commercial-policy';
type Metric={id:string;day:string;campaignId:string;type:string;creativeId?:string;impression?:number;click?:number};
type Campaign={id:string;businessName:string;status:string;startAt?:string;endAt:string;communes?:string[];placements?:string[]};
export function CommercialControls(){
  const [config,setConfig]=useState<CommercialConfig|null>(null);
  const [rows,setRows]=useState<Campaign[]>([]);const [cursor,setCursor]=useState<string|null>(null);
  const [metrics,setMetrics]=useState<Metric[]>([]);const [metricCursor,setMetricCursor]=useState<string|null>(null);const [metricsLoaded,setMetricsLoaded]=useState(false);
  const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');
  const measured=metrics.reduce((a,m)=>({
    impressions:a.impressions+(m.impression||0),clicks:a.clicks+(m.click||0)
  }),{impressions:0,clicks:0});
  const campaignTotals=Object.values(metrics.reduce((sum,m)=>{
    const key=m.campaignId;
    const row=sum[key]||(sum[key]={id:key,impressions:0,clicks:0});
    row.impressions+=m.impression||0;row.clicks+=m.click||0;
    return sum;
  },{} as Record<string,{id:string;impressions:number;clicks:number}>))
    .sort((a,b)=>b.impressions-a.impressions);
  function exportLoadedMetrics() {
    if(!metrics.length)return;
    const lines=[['fecha','campaña','espacio','impresiones','clics','ctr_porcentaje'],
      ...metrics.map(m=>[m.day,m.campaignId,m.creativeId||'no_indicado',
        String(m.impression||0),String(m.click||0),
        m.impression?((m.click||0)/m.impression*100).toFixed(2):'0.00'])];
    const quoted=(s:string)=>{
      const value=/^[=+@-]/.test(s)?String.fromCharCode(39)+s:s;
      return '"'+value.replace(/"/g,'""')+'"';
    };
    const csv=String.fromCharCode(0xFEFF)+lines.map(row=>row.map(quoted).join(';')).join(String.fromCharCode(13,10));
    const uri=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));
    const a=document.createElement('a');a.href=uri;
    a.download='trabajo-cerca-publicidad-laboratorio.csv';
    document.body.appendChild(a);a.click();a.remove();
    window.setTimeout(()=>URL.revokeObjectURL(uri),1000);
  }
  const [publicChecks,setPublicChecks]=useState<Record<string,string>>({});
  useEffect(()=>{let active=true;void api.get('/api/admin/marketing/commercial').then(r=>{if(active)setConfig(r.data);}).catch(()=>{if(active)setMessage('No se pudo leer la configuración comercial.');});return()=>{active=false;};},[]);
  function update(patch:Partial<CommercialConfig>){setConfig(c=>c?{...c,...patch}:c);}
  async function save(){setBusy(true);try{const r=await api.put('/api/admin/marketing/commercial',config);setConfig(r.data);setMessage('Promoción guardada. No se activaron anuncios ni cobros.');}catch{setMessage('No se guardó. Revisa los datos y recarga: otra aprobación puede haber cambiado los cupos.');}finally{setBusy(false);}}
  async function load(more=false){setBusy(true);try{const r=await api.get('/api/admin/marketing/campaigns'+(more?'?cursor='+encodeURIComponent(cursor||''):''));setRows(old=>more?[...old,...r.data.items]:r.data.items);setCursor(r.data.nextToken);}catch{setMessage('No se completó la consulta de campañas.');}finally{setBusy(false);}}
  async function loadMetrics(more=false){setBusy(true);try{const r=await api.get('/api/admin/marketing/commercial-metrics'+(more?'?cursor='+encodeURIComponent(metricCursor||''):''));setMetrics(old=>more?[...old,...r.data.items]:r.data.items);setMetricCursor(r.data.nextToken);setMetricsLoaded(true);}catch{setMessage('No se completó la lectura de métricas comerciales.');}finally{setBusy(false);}}
  async function status(id:string,status:string){setBusy(true);try{await api.put('/api/admin/marketing/campaigns',{id,status});setRows(old=>old.map(r=>r.id===id?{...r,status}:r));setMessage('Estado actualizado. No se modificaron fechas ni beneficios.');}catch{setMessage('No se cambió el estado; una campaña vencida no puede renovarse así.');}finally{setBusy(false);}}

 async function checkPublic(row:Campaign) {
    const place=row.communes?.includes('Mininco')?'Mininco':row.communes?.find(p=>p!=='Todas')||'Todas';
    setPublicChecks(old=>({...old,[row.id]:'Consultando catálogo público…'}));
    try {
      const result=await api.get('/api/growth/advertising?place='+encodeURIComponent(place)+'&turn=1');
      const found=Array.isArray(result.data?.commercial)&&result.data.commercial.some((item:{id:string})=>item.id===row.id);
      setPublicChecks(old=>({...old,[row.id]:found
        ? 'Incluida en el catálogo público para '+place+'. Verifica también su visualización en pantalla.'
        : 'No figura en la selección pública para '+place+'. Revisa cobertura, fecha y prioridad.'}));
    } catch {
      setPublicChecks(old=>({...old,[row.id]:'No fue posible consultar el catálogo público.'}));
    }
  }

 const [coverageId,setCoverageId]=useState('');
 const [coveragePlaces,setCoveragePlaces]=useState<string[]>([]);
 const [coverageSlots,setCoverageSlots]=useState<string[]>([]);
 const [coveragePlan,setCoveragePlan]=useState<'basic'|'featured'|'multi'>('basic');
 function selectCoverage(row:Campaign){setCoverageId(row.id);setCoveragePlaces(row.communes||[]);setCoverageSlots(row.placements||['search']);setMessage('');}
 async function saveCoverage(){setBusy(true);try{const result=await api.post('/api/admin/marketing/coverage',{id:coverageId,communes:coveragePlaces,placements:coverageSlots,plan:coveragePlan});setMessage(result.data.notice||'Propuesta guardada.');setCoverageId('');}catch{setMessage('No se guardó la propuesta: selecciona una nueva comuna o espacio.');}finally{setBusy(false);}}

  return <section aria-label='Promociones y campañas comerciales'><h3>Promoción vigente</h3><p>La fecha oficial solo se configura cuando el lanzamiento esté aprobado. Una promoción por negocio revisado; beneficios no acumulables.</p><p role='status'>{message}</p>
    {config&&<fieldset disabled={busy}><legend>Configuración centralizada</legend>
      <label><input type='checkbox' checked={config.enabled} onChange={e=>update({enabled:e.target.checked})}/>Promoción habilitada</label>
      <label>Lanzamiento aprobado, UTC; vacío = sin lanzamiento<input type='datetime-local' value={config.launchAt?.slice(0,16)||''} onChange={e=>update({launchAt:e.target.value?new Date(e.target.value+'Z').toISOString():null})}/></label>
      <label>Cierre de convocatoria UTC, opcional<input type='datetime-local' value={config.founderClosesAt?.slice(0,16)||''} onChange={e=>update({founderClosesAt:e.target.value?new Date(e.target.value+'Z').toISOString():null})}/></label>
      {([['founderSlots','Cupos fundadores'],['founderDays','Días por fundador'],['founderWindowDays','Días de convocatoria desde lanzamiento'],['standardDays','Días de prueba estándar']] as const).map(([key,label])=><label key={key}>{label}<input type='number' min='1' max={key==='founderSlots'?10000:365} value={config[key]} onChange={e=>update({[key]:Number(e.target.value)})}/></label>)}
      <p>Cupos otorgados: {config.foundersUsed}. Disponibles: {Math.max(0,config.founderSlots-config.foundersUsed)}. No son ingresos.</p>
      <label><input type='checkbox' checked={config.standardEnabled} onChange={e=>update({standardEnabled:e.target.checked})}/>Prueba estándar al cerrar fundadores</label>
      <label>Mensaje público<textarea maxLength={300} value={config.message} onChange={e=>update({message:e.target.value})}/></label>
      <label>Condiciones<textarea maxLength={1000} value={config.conditions} onChange={e=>update({conditions:e.target.value})}/></label>
      <details><summary>Planes referenciales, sin contratación ni pagos habilitados</summary>{config.plans.map((plan,index)=><div key={plan.id}><b>{plan.id}</b><label>Precio referencial CLP / {plan.days} días<input type='number' min='0' value={plan.priceCLP} onChange={e=>update({plans:config.plans.map((p,i)=>i===index?{...p,priceCLP:Number(e.target.value)}:p)})}/></label><label>IVA<select value={plan.vat} onChange={e=>update({plans:config.plans.map((p,i)=>i===index?{...p,vat:e.target.value as typeof p.vat}:p)})}><option value='pending'>Pendiente de definición</option><option value='included'>Incluido</option><option value='excluded'>No incluido</option></select></label></div>)}</details>
      <button type='button' onClick={()=>void save()}>Guardar promoción y tarifas preliminares</button>
    </fieldset>}
    <h3>Rendimiento comercial</h3><p><strong>LABORATORIO · DEMOSTRACIÓN</strong>. Las métricas actuales provienen de campañas de prueba y no deben presentarse como resultados de clientes reales. Una impresión visible indica exposición del anuncio; los clics a WhatsApp no demuestran conversaciones ni ventas.</p><button disabled={busy} onClick={()=>void loadMetrics()}>Consultar métricas comerciales</button>
    {metricsLoaded&&metrics.length>0&&<div className='tcCampaignMetricTotals'>
      <strong>Resumen del tramo cargado</strong>
      <div><span><b>{measured.impressions}</b><small>Impresiones visibles</small></span>
      <span><b>{measured.clicks}</b><small>Clics reportados</small></span>
      <span><b>{measured.impressions?(measured.clicks/measured.impressions*100).toFixed(1):'0'}%</b><small>CTR de este tramo</small></span></div>
      <p>Datos de prueba, no personas únicas ni ventas. Las páginas aún no cargadas no se incluyen.</p>
      <button type='button' onClick={exportLoadedMetrics}>Exportar CSV del tramo cargado</button>
      <div className='tcCampaignByAdvertiser' aria-label='Resultados por anunciante del tramo cargado'>
        <strong>Por campaña · laboratorio</strong>
        {campaignTotals.map(row=><p key={row.id}>
          <b>{rows.find(c=>c.id===row.id)?.businessName||row.id}</b>:
          {' '}{row.impressions} impresiones · {row.clicks} clics ·
          {' '}{row.impressions?(row.clicks/row.impressions*100).toFixed(1):'0'}% CTR
        </p>)}
      </div>
    </div>}
    {!metrics.length&&<p>{metricsLoaded?'Sin datos':'Sin datos cargados'}</p>
    }{metrics.map(m=><article key={m.id} className='tcCampaignMetricCard'>
      <strong>{rows.find(row=>row.id===m.campaignId)?.businessName||m.campaignId}</strong>
      <small>{m.day} · Espacio: {m.creativeId==='search'?'Buscador':m.creativeId==='listing'?'Entre resultados':m.creativeId==='featured'?'Destacado':m.creativeId==='form'?'Formulario':m.creativeId||'General'} · Laboratorio</small>
      <p><b>{m.impression||0}</b> impresiones visibles · <b>{m.click||0}</b> clics · CTR <b>{m.impression?((m.click||0)/m.impression*100).toFixed(1):'0'}%</b></p>
      <small>No representa usuarios únicos, consultas respondidas ni ventas.</small>
    </article>)}
    {metricCursor&&<button disabled={busy} onClick={()=>void loadMetrics(true)}>Cargar más métricas comerciales</button>}
    <h3>Campañas comerciales</h3><button disabled={busy} onClick={()=>void load()}>Consultar campañas</button>
    {!rows.length&&<p>Sin datos cargados.</p>}
    {rows.map(row=><article key={row.id} className='tcCampaignRow'>
      <b>{row.businessName}</b>
      <p>Estado: {row.status==='active'?'Activa':row.status} · Fin de vigencia interno: {new Date(row.endAt).toLocaleDateString('es-CL')}</p>
      <p>Territorios: {row.communes?.join(', ')||'No configurados'} · Espacios: {(row.placements||['search']).map(p=>p==='search'?'Bajo buscador':'Entre resultados').join(', ')}</p>
      <button type='button' disabled={busy} onClick={()=>void checkPublic(row)}>Comprobar catálogo público</button>
      {publicChecks[row.id]&&<p role='status'>{publicChecks[row.id]}</p>}{(['active','paused','rejected'] as const).map(value=><button key={value} disabled={busy||row.status===value} onClick={()=>void status(row.id,value)}>{value==='active'?'Activar':value==='paused'?'Pausar':'Rechazar'}</button>)} <button type='button' disabled={busy} onClick={()=>selectCoverage(row)}>Agregar comunas o espacios</button></article>)}
    {coverageId&&<section className='tcCoverageProposal' aria-label='Propuesta de ampliación comercial'>
 <h4>Ampliar publicidad</h4><p>Selecciona comunas y espacios adicionales. Se guardará como propuesta pendiente: sin cobro ni publicación automática.</p>
 <label>Modalidad<select value={coveragePlan} onChange={e=>setCoveragePlan(e.target.value as typeof coveragePlan)}><option value='basic'>Básica</option><option value='featured'>Destacada</option><option value='multi'>Multicomuna</option></select></label>
 <fieldset><legend>Comunas</legend><div className='tcCoverageOptions'>{COMMERCIAL_PLACES.map(place=><label key={place}><input type='checkbox' checked={coveragePlaces.includes(place)} onChange={e=>setCoveragePlaces(x=>e.target.checked?[...x,place]:x.filter(v=>v!==place))}/>{place}</label>)}</div></fieldset>
 <fieldset><legend>Espacios disponibles actualmente</legend>{([['search','Junto al buscador'],['listing','Entre resultados']] as const).map(([id,label])=><label key={id}><input type='checkbox' checked={coverageSlots.includes(id)} onChange={e=>setCoverageSlots(x=>e.target.checked?[...x,id]:x.filter(v=>v!==id))}/>{label}</label>)}</fieldset>
 <button type='button' disabled={busy} onClick={()=>void saveCoverage()}>Guardar propuesta sin publicar</button> <button type='button' disabled={busy} onClick={()=>setCoverageId('')}>Cancelar</button>
 </section>}
    {cursor&&<button disabled={busy} onClick={()=>void load(true)}>Cargar más campañas</button>
  }</section>;
}

